import subprocess

class LocalCheckoutManager:
    def __init__(self, repository_path):
        self.repository_path = repository_path

    def clone_repository(self, remote_url):
        try:
            subprocess.run(['git', 'clone', remote_url], cwd=self.repository_path, check=True)
            print(f"Repository cloned successfully to {self.repository_path}")
        except subprocess.CalledProcessError as e:
            print(f"Failed to clone repository: {e}")

    def checkout_branch(self, branch_name):
        try:
            subprocess.run(['git', 'checkout', branch_name], cwd=self.repository_path, check=True)
            print(f"Switched to branch: {branch_name}")
        except subprocess.CalledProcessError as e:
            print(f"Failed to checkout branch: {e}")

    def pull_latest_changes(self):
        try:
            subprocess.run(['git', 'pull'], cwd=self.repository_path, check=True)
            print("Successfully pulled latest changes")
        except subprocess.CalledProcessError as e:
            print(f"Failed to pull latest changes: {e}")

    def create_and_checkout_new_branch(self, new_branch_name):
        try:
            subprocess.run(['git', 'checkout', '-b', new_branch_name], cwd=self.repository_path, check=True)
            print(f"Created and switched to new branch: {new_branch_name}")
        except subprocess.CalledProcessError as e:
            print(f"Failed to create and switch to new branch: {e}")

