        if not ftp:
            return False

        for file in files:
            local_file_path = os.path.join(self.local_path, file)
            if os.path.isfile(local_file_path):
                try:
                    with open(local_file_path, 'rb') as f:
                        ftp.storbinary(f'STOR {os.path.join(self.remote_path, file)}', f)
