class NetworkBackupTool:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.sock = None

    def connect(self):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            self.sock.connect((self.host, self.port))
        except Exception as e:
            print(f"Failed to connect: {e}")
            raise

    def disconnect(self):
        if self.sock:
            self.sock.close()
            self.sock = None

    def upload_file(self, local_path, remote_name=None):
        if not remote_name:
            remote_name = os.path.basename(local_path)

        with open(local_path, 'rb') as f:
            file_data = f.read()

        timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
        header = f"{remote_name},{timestamp}\n"

        try:
            self.sock.sendall(header.encode())
            response = self.sock.recv(1024).decode().strip()
            if response == "OK":
                self.sock.sendall(file_data)
                response = self.sock.recv(1024).decode().strip()
                if response == "FILE_RECEIVED":
                    print(f"File {local_path} successfully backed up.")
                else:
                    print(f"Error receiving file response: {response}")
            else:
                print(f"Error sending file header: {response}")
        except Exception as e:
            print(f"An error occurred during file upload: {e}")

if __name__ == "__main__":
    backup_tool = NetworkBackupTool('192.168.1.100', 5000)
    backup_tool.connect()
    backup_tool.upload_file('/path/to/local/file.txt')
    backup_tool.disconnect()
