        self.host = host
        self.port = port
        self.password = password
        self.local_dir = '/path/to/local/directory'
        self.remote_dir = f'/home/{user}@{host}:/path/to/remote/directory'

        self.ssh_client = paramiko.SSHClient()
        self.ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    def connect(self):
        try:
            self.ssh_client.connect(hostname=self.host, username=self.user, port=self.port, password=self.password)
        except paramiko.AuthenticationException as e:
            print(f"Authentication failure: {e}")

    def send_file(self, local_file):
        self.connect()
        sftp = self.ssh_client.open_sftp()
        try:
            filename = os.path.basename(local_file)
            file_hash = self.generate_hash(local_file)
            sftp.put(local_file, f'{self.remote_dir}/{filename}')
            sftp.close()
        except Exception as e:
            print(f"Error sending file: {e}")

    def receive_file(self, remote_file):
        self.connect()
        sftp = self.ssh_client.open_sftp()
        try:
            filename = os.path.basename(remote_file)
            file_hash = self.generate_hash(remote_file)
            sftp.get(f'{self.remote_dir}/{filename}', filename)
            sftp.close()
        except Exception as e:
            print(f"Error receiving file: {e}")

    def generate_hash(self, file):
        md5 = hashlib.md5()
        with open(file, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5.update(chunk)
        return md5.hexdigest()

