        for file in os.listdir(self.local_dir):
            local_file = f'{self.local_dir}/{file}'
            if os.path.isfile(local_file):
                self.receive_file(remote_file=f'{self.remote_dir}/{file}')
            else:
                self.sync_dir(local_file)

